const app = getApp()
var db = wx.cloud.database()

Page({
  data: {
    myOrders: [],
    selectedOrder: null,
    complaintType: '',
    complaintContent: '',
    submitting: false
  },

  onLoad: function() {
    this.loadMyOrders()
  },

  loadMyOrders: function() {
    var that = this
    var userInfo = app.globalData.userInfo || {}
    var myOpenId = userInfo._openid || ''
    if (!myOpenId) {
      wx.showToast({ title: '请先登录', icon: 'none' })
      return
    }
    wx.cloud.callFunction({
      name: 'login',
      data: { action: 'getMyRelatedOrders', _openid: myOpenId },
      success: function(res) {
        if (res.result && res.result.code === 0) {
          var list = (res.result.data || []).map(function(o) {
            var statusMap = { pending: '待接单', accepted: '进行中', delivering: '配送中', delivered: '待确认', paid: '已完成', completed: '已完成', cancelled: '已取消' }
            o.statusText = statusMap[o.status] || o.status || '未知'
            var d = o.createTime ? new Date(o.createTime) : null
            o.createTimeText = d ? (d.getMonth()+1) + '/' + d.getDate() + ' ' + d.getHours() + ':' + String(d.getMinutes()).padStart(2,'0') : ''
            o.typeText = o.publisherId === myOpenId ? '我发布的' : '我接的单'
            return o
          })
          that.setData({ myOrders: list })
        }
      }
    })
  },

  selectOrder: function(e) {
    var index = e.currentTarget.dataset.index
    this.setData({ selectedOrder: index })
  },

  bindTypeInput: function(e) {
    this.setData({ complaintType: e.detail.value })
  },

  bindContentInput: function(e) {
    this.setData({ complaintContent: e.detail.value })
  },

  submitComplaint: function() {
    var that = this
    var orderIndex = that.data.selectedOrder
    if (orderIndex === null || orderIndex === undefined) {
      wx.showToast({ title: '请选择关联订单', icon: 'none' })
      return
    }
    var order = that.data.myOrders[orderIndex]
    if (!order) {
      wx.showToast({ title: '请选择关联订单', icon: 'none' })
      return
    }
    var userInfo = app.globalData.userInfo || {}
    var content = that.data.complaintContent.trim()
    if (!content) {
      wx.showToast({ title: '请描述投诉内容', icon: 'none' })
      return
    }
    if (that.data.submitting) return
    that.setData({ submitting: true })
    wx.showLoading({ title: '提交中' })

    wx.cloud.callFunction({
      name: 'login',
      data: {
        action: 'submitComplaint',
        orderId: order._id,
        orderNo: order.orderNo || order._id,
        content: content,
        complaintType: that.data.complaintType.trim(),
        targetUserId: order.publisherId === (userInfo._openid || '') ? order.acceptorId : order.publisherId,
        targetUserName: order.publisherId === (userInfo._openid || '') ? (order.acceptorName || '接单者') : (order.publisherName || '发布者'),
        complainantName: userInfo.nickName || '用户',
        complainantPhone: userInfo.phone || ''
      },
      success: function(res) {
        wx.hideLoading()
        that.setData({ submitting: false })
        if (res.result && res.result.code === 0) {
          wx.showToast({ title: '投诉已提交', icon: 'success' })
          setTimeout(function() { wx.navigateBack() }, 1500)
        } else {
          wx.showToast({ title: (res.result && res.result.msg) || '提交失败', icon: 'none' })
        }
      },
      fail: function() {
        wx.hideLoading()
        that.setData({ submitting: false })
        wx.showToast({ title: '网络错误', icon: 'none' })
      }
    })
  }
})
